int countWindows(const vector<int>& a,
                 int k, int t) {
    int s = 0;
    for (int i = 0; i < k; i++) s += a[i];
    int cnt = s >= t ? 1 : 0;
    for (int i = k; i < (int)a.size(); i++) {
        s += a[i] - a[___];
